#include "scene.h"
#include <limits.h>
#include <math.h>
#include <string.h>
#define NONE 65535u
#define Q OSG_EXPRESSION_Q
#define REQUIRE(x) do { if(!(x)) return false; } while(0)
typedef struct { int x,y,w,h; } box;
typedef struct { int32_t lo,hi; bool boolean; } interval;
const osg_scene_profile OSG_SCENE_SUNTON={480,320,0,24,480,288,&OSG_RENDER_SUNTON_LIMITS,8,16384,16384};
const osg_scene_profile OSG_SCENE_WAVESHARE={800,480,0,24,800,448,&OSG_RENDER_WAVESHARE_LIMITS,16,96000,192000};
_Static_assert(sizeof(osg_scene)<=24*1024,"Scene runtime exceeds Sunton working-set ceiling");
static uint16_t u16(const uint8_t *p){return (uint16_t)((uint16_t)p[0]|(uint16_t)p[1]<<8);}
static uint32_t u32(const uint8_t *p){return (uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static int32_t i32(const uint8_t *p){uint32_t v=u32(p);return v<=INT32_MAX?(int32_t)v:-1-(int32_t)(UINT32_MAX-v);}
static int s16(const uint8_t *p){unsigned v=u16(p);return v<=INT16_MAX?(int)v:(int)v-65536;}
static bool zeros(const uint8_t *p,size_t n){for(size_t i=0;i<n;i++)if(p[i])return false;return true;}
static box rect(const uint8_t *p){return (box){s16(p),s16(p+2),u16(p+4),u16(p+6)};}
static box content(const osg_scene *s){return (box){s->profile->x,s->profile->y,s->profile->content_width,s->profile->content_height};}
static bool contains(box a,box b){return b.w>0&&b.h>0&&b.x>=a.x&&b.y>=a.y&&b.x+b.w<=a.x+a.w&&b.y+b.h<=a.y+a.h;}
static box intersect(box a,box b){int x=a.x>b.x?a.x:b.x,y=a.y>b.y?a.y:b.y,r=a.x+a.w<b.x+b.w?a.x+a.w:b.x+b.w,d=a.y+a.h<b.y+b.h?a.y+a.h:b.y+b.h;return (box){x,y,r>x?r-x:0,d>y?d-y:0};}
static bool inside(box b,int x,int y){return x>=b.x&&y>=b.y&&x<b.x+b.w&&y<b.y+b.h;}
static const osg_render_section *table(const osg_scene *s,unsigned object,unsigned kind){if(object>=4)return NULL;for(unsigned i=0;i<s->object[object].section_count;i++)if(s->object[object].sections[i].kind==kind)return &s->object[object].sections[i];return NULL;}
static uint32_t count(const osg_scene *s,unsigned object,unsigned kind){const osg_render_section *t=table(s,object,kind);return t?t->count:0;}
static bool read_at(osg_scene *s,unsigned object,uint32_t at,void *out,size_t n){if(object>=4||at>s->source[object].bytes||n>s->source[object].bytes-at){s->failed=true;return false;}uint8_t *p=out;while(n){size_t step=n>32?32:n;if(!s->source[object].read||!s->source[object].read(s->source[object].context,at,p,step)){s->failed=true;return false;}at+=(uint32_t)step;p+=step;n-=step;}return true;}
bool osg_scene_record(osg_scene *s,unsigned object,unsigned kind,uint32_t index,void *record,size_t bytes){if(!s||!record)return false;const osg_render_section *t=table(s,object,kind);if(!t||index>=t->count||bytes!=t->record_bytes){s->failed=true;return false;}return read_at(s,object,t->offset+index*t->record_bytes,record,bytes);}
static bool utf8(const uint8_t *p,size_t n,size_t *used,uint32_t *out){if(!n)return false;uint32_t cp=p[0];unsigned length=1;if(cp>=0xc2&&cp<=0xdf){cp&=31;length=2;}else if(cp>=0xe0&&cp<=0xef){cp&=15;length=3;}else if(cp>=0xf0&&cp<=0xf4){cp&=7;length=4;}else if(cp>=128)return false;if(length>n)return false;for(unsigned i=1;i<length;i++){if((p[i]&0xc0)!=0x80)return false;cp=cp<<6|(p[i]&63);}if((length==2&&cp<128)||(length==3&&cp<2048)||(length==4&&cp<65536)||cp>0x10ffff||(cp>=0xd800&&cp<=0xdfff)||cp<32||cp==127)return false;*out=cp;*used=length;return true;}
static bool string(osg_scene *s,unsigned object,unsigned section,uint32_t offset,uint16_t bytes,bool identifier){const osg_render_section *t=table(s,object,section);uint8_t value[120];REQUIRE(bytes<=sizeof(value)&&(!identifier||bytes>0));REQUIRE(t&&offset<=t->length&&bytes<=t->length-offset&&read_at(s,object,t->offset+offset,value,bytes));for(size_t i=0;i<bytes;){size_t used;uint32_t cp;REQUIRE(utf8(value+i,bytes-i,&used,&cp));if(identifier){bool alnum=(cp>='A'&&cp<='Z')||(cp>='a'&&cp<='z')||(cp>='0'&&cp<='9');REQUIRE(alnum||(i&&(cp=='_'||cp=='.'||cp=='-')));}i+=used;}return true;}
static bool stable_ids(osg_scene *s,unsigned object,unsigned section,unsigned strings){uint8_t a[64],b[64];for(uint32_t i=0;i<count(s,object,section);i++){const osg_render_section *t=table(s,object,section);REQUIRE(t->record_bytes<=sizeof(a)&&osg_scene_record(s,object,section,i,a,t->record_bytes));unsigned n=u16(a+4);REQUIRE(n<=96&&string(s,object,strings,u32(a),(uint16_t)n,true));for(uint32_t j=0;j<i;j++){REQUIRE(osg_scene_record(s,object,section,j,b,t->record_bytes));if(u16(b+4)==n){uint8_t x[96],y[96];const osg_render_section *str=table(s,object,strings);REQUIRE(read_at(s,object,str->offset+u32(a),x,n)&&read_at(s,object,str->offset+u32(b),y,n));REQUIRE(memcmp(x,y,n));}}}return true;}
static bool images_valid(osg_scene *s){uint8_t image[24],pad;const osg_render_section *pixels=table(s,2,2);if(!s->source[2].bytes)return true;REQUIRE(count(s,2,1)&&pixels);for(uint32_t i=0;i<count(s,2,1);i++){REQUIRE(osg_scene_record(s,2,1,i,image,24));unsigned w=u16(image),h=u16(image+2),format=image[16];uint32_t stride=u32(image+4),offset=u32(image+8),bytes=u32(image+12);REQUIRE(w&&w<=800&&h&&h<=480&&(format==1||format==2)&&zeros(image+17,7));REQUIRE(stride==(format==1?w*2:(w+1)/2)&&bytes==stride*h&&offset<=pixels->length&&bytes<=pixels->length-offset);if(format==2&&w%2)for(unsigned y=0;y<h;y++){REQUIRE(read_at(s,2,pixels->offset+offset+y*stride+stride-1,&pad,1)&&!(pad&15));}}return true;}
static bool fonts_valid(osg_scene *s){if(!s->source[3].bytes)return true;uint8_t font[16],glyph[24],pad,owned[512/8]={0};const osg_render_section *pixels=table(s,3,3);uint32_t glyphs=count(s,3,2),seen=0;REQUIRE(count(s,3,1)&&glyphs&&glyphs<=s->profile->limits->glyphs&&glyphs<=512&&pixels);for(uint32_t f=0;f<count(s,3,1);f++){REQUIRE(osg_scene_record(s,3,1,f,font,16));uint32_t first=u16(font),n=u16(font+2),fallback=u16(font+4);REQUIRE(n&&first<=glyphs&&n<=glyphs-first&&fallback>=first&&fallback<first+n&&u16(font+6)&&zeros(font+10,6));REQUIRE(osg_scene_record(s,3,2,fallback,glyph,24)&&u32(glyph)==63);uint32_t previous=0;for(uint32_t i=first;i<first+n;i++){REQUIRE(!(owned[i/8]&(1u<<(i%8))));owned[i/8]|=(uint8_t)(1u<<(i%8));seen++;REQUIRE(osg_scene_record(s,3,2,i,glyph,24));uint32_t cp=u32(glyph),w=u16(glyph+4),h=u16(glyph+6),offset=u32(glyph+16),bytes=u32(glyph+20),stride=(w+1)/2;REQUIRE(cp<=0x10ffff&&!(cp>=0xd800&&cp<=0xdfff)&&(i==first||cp>previous));previous=cp;REQUIRE(w<=256&&h<=256&&s16(glyph+8)>=0&&s16(glyph+12)>=s16(glyph+8)+(int)w&&zeros(glyph+14,2)&&bytes==stride*h&&offset<=pixels->length&&bytes<=pixels->length-offset);if(w%2)for(uint32_t y=0;y<h;y++)REQUIRE(read_at(s,3,pixels->offset+offset+y*stride+stride-1,&pad,1)&&!(pad&15));}}return seen==glyphs;}
static bool semantics_valid(osg_scene *s){uint8_t r[32],control[32];uint32_t controls=count(s,0,1),outputs=count(s,0,2),interactions=count(s,0,3);uint32_t owned=0;REQUIRE(controls<=32&&outputs<=64&&interactions<=32);REQUIRE(stable_ids(s,0,1,4)&&stable_ids(s,0,2,4)&&stable_ids(s,0,3,4));for(uint32_t i=0;i<controls;i++){REQUIRE(osg_scene_record(s,0,1,i,r,32));unsigned kind=r[6];REQUIRE(kind>=1&&kind<=3&&!r[7]&&i32(r+16)==(kind==3?-Q:0)&&i32(r+20)==Q&&i32(r+24)>=i32(r+16)&&i32(r+24)<=Q&&(kind!=1||!i32(r+24)));REQUIRE(u16(r+12)<=96&&string(s,0,4,u32(r+8),u16(r+12),true));}for(uint32_t i=0;i<outputs;i++){REQUIRE(osg_scene_record(s,0,2,i,r,32));unsigned kind=r[6],text=u16(r+14);REQUIRE(kind>=1&&kind<=3&&!r[7]&&zeros(r+30,2)&&i32(r+16)<=i32(r+20)&&text<=120);REQUIRE(kind==3?(text&&i32(r+16)==0&&i32(r+20)==0):text==0);REQUIRE(kind!=1||(i32(r+16)==0&&i32(r+20)==Q));REQUIRE(u16(r+12)&&u16(r+12)<=96&&string(s,0,4,u32(r+8),u16(r+12),false)&&u16(r+28)<=24&&string(s,0,4,u32(r+24),u16(r+28),false));}for(uint32_t i=0;i<interactions;i++){REQUIRE(osg_scene_record(s,0,3,i,r,24));REQUIRE((r[6]==1||r[6]==2)&&!r[7]&&u16(r+10)==NONE&&u16(r+12)==NONE&&!u16(r+16)&&zeros(r+18,6));unsigned member=u16(r+8);if(r[6]==2){REQUIRE(member==NONE&&u16(r+14)<s->pages);}else{REQUIRE(member<controls&&!(owned&(UINT32_C(1)<<member))&&u16(r+14)==NONE);owned|=UINT32_C(1)<<member;REQUIRE(osg_scene_record(s,0,1,member,control,32)&&control[6]==1&&u16(control+28)==i&&u16(control+30)==NONE);}}return owned==(controls==32?UINT32_MAX:((UINT32_C(1)<<controls)-1));}
static bool image_ref(osg_scene *s,const uint8_t *node,unsigned index,unsigned format){uint8_t image[24];REQUIRE(index<count(s,2,1)&&osg_scene_record(s,2,1,index,image,24));return image[16]==format&&u16(node+52)+u16(node+8)<=u16(image)&&u16(node+54)+u16(node+10)<=u16(image+2);}
static bool nodes_valid(osg_scene *s){uint8_t page[16],node[64],point[4];uint32_t cursor=0;REQUIRE(stable_ids(s,1,1,10));for(unsigned p=0;p<s->pages;p++){REQUIRE(osg_scene_record(s,1,1,p,page,16)&&zeros(page+12,4));uint32_t first=u16(page+6),n=u16(page+8);REQUIRE(first==cursor&&n<=s->nodes-first);for(uint32_t i=first;i<first+n;i++)REQUIRE(osg_scene_record(s,1,2,i,node,64)&&u16(node)==p);cursor+=n;if(n>s->usage.max_page_draw_ops)s->usage.max_page_draw_ops=n;}REQUIRE(cursor==s->nodes);for(unsigned i=0;i<s->nodes;i++){REQUIRE(osg_scene_record(s,1,2,i,node,64));unsigned op=node[2];box initial=rect(node+4),clip=rect(node+12),reach=rect(node+20);REQUIRE(op>=1&&op<=7&&!(node[3]&~1)&&contains(content(s),reach)&&contains(reach,initial)&&contains(content(s),clip)&&zeros(node+56,8));REQUIRE(op==2||op==4?image_ref(s,node,u16(node+28),1):u16(node+28)==NONE);REQUIRE(op==3||op==4?image_ref(s,node,u16(node+30),2):u16(node+30)==NONE);if(op==5){REQUIRE(u16(node+32)<count(s,3,1)&&u16(node+50)&&u16(node+50)<=120&&u16(node+48)<=u16(node+50)&&u16(node+42)<=4&&string(s,1,10,u32(node+44),u16(node+48),false));}else REQUIRE(u16(node+32)==NONE&&!u16(node+42)&&!u32(node+44)&&!u16(node+48)&&!u16(node+50));if(op>=6){unsigned first=u16(node+38),n=u16(node+40);REQUIRE(u16(node+34)&&u16(node+34)<=16&&n>=2&&n<=64&&(op!=6||n==2)&&first<=count(s,1,9)&&n<=count(s,1,9)-first);for(unsigned j=first;j<first+n;j++)REQUIRE(osg_scene_record(s,1,9,j,point,4)&&contains(reach,(box){s16(point),s16(point+2),1,1}));}else REQUIRE(!u16(node+34)&&!u16(node+38)&&!u16(node+40));if(op!=2&&op!=3&&op!=4)REQUIRE(!u16(node+52)&&!u16(node+54));}return true;}static bool scalar64(int64_t value,int32_t *out){if(value<INT32_MIN||value>INT32_MAX)return false;*out=(int32_t)value;return true;}
static interval iv(int32_t lo,int32_t hi){return (interval){lo,hi,lo==hi&&(lo==0||lo==Q)};}
static bool lookup_endpoint(osg_scene *s,unsigned first,unsigned n,int32_t input,int32_t *out){uint8_t point[8];int32_t previous_x=0,previous_y=0;for(unsigned j=0;j<n;j++){REQUIRE(osg_scene_record(s,1,13,first+j,point,8));int32_t x=i32(point),y=i32(point+4);if(!j&&input<=x){*out=y;return true;}if(j&&input<=x){int64_t dy=(int64_t)y-previous_y;uint64_t amount=(uint64_t)((int64_t)input-previous_x)*(uint64_t)(dy<0?-dy:dy)/(uint64_t)((int64_t)x-previous_x);return scalar64((int64_t)previous_y+(dy<0?-(int64_t)amount:(int64_t)amount),out);}previous_x=x;previous_y=y;}*out=previous_y;return true;}
static bool interval_eval(osg_scene *s,unsigned first,unsigned n,interval *result,uint32_t *work){interval stack[8];unsigned depth=0;uint8_t ins[16],v[24],point[8];REQUIRE(n&&n<=1024&&first<=count(s,1,5)&&n<=count(s,1,5)-first);for(unsigned i=first;i<first+n;i++){REQUIRE(osg_scene_record(s,1,5,i,ins,16)&&!ins[1]&&zeros(ins+8,8));unsigned op=ins[0],arg=u16(ins+2);int32_t value=i32(ins+4);REQUIRE(op>=1&&op<=16);REQUIRE(op==1?!arg:op==2?!value:op==16?true:!arg&&!value);unsigned inputs=op<=2?0:op==13||op==16?1:op==14||op==15?3:2;REQUIRE(depth>=inputs&&depth-inputs<8);interval r=iv(0,0),a=iv(0,0),b=iv(0,0);if(inputs){a=stack[depth-inputs];b=stack[depth-1];}(*work)++;if(op==1)r=iv(value,value);else if(op==2){REQUIRE(arg<s->variables&&osg_scene_record(s,1,3,arg,v,24)&&v[2]!=3);r=iv(i32(v+8),i32(v+12));r.boolean=v[2]==1;}else if(op==13){REQUIRE(a.boolean);r=(interval){0,Q,true};}else if(op==14){REQUIRE(a.boolean);interval yes=stack[depth-2];r=iv(yes.lo<b.lo?yes.lo:b.lo,yes.hi>b.hi?yes.hi:b.hi);r.boolean=yes.boolean&&b.boolean;if(a.lo==a.hi)r=a.lo?yes:b;}else if(op==15){interval min=stack[depth-2],max=stack[depth-1];REQUIRE(min.hi<=max.lo);int32_t lo=a.lo<min.lo?min.lo:a.lo>max.lo?max.lo:a.lo,hi=a.hi<min.hi?min.hi:a.hi>max.hi?max.hi:a.hi;r=iv(lo,hi);}else if(op==16){REQUIRE(value>=2&&value<=256&&arg<=count(s,1,13)&&(uint32_t)value<=count(s,1,13)-arg);int32_t previous=0;bool have=false;for(unsigned j=0;j<(unsigned)value;j++){REQUIRE(osg_scene_record(s,1,13,arg+j,point,8));int32_t x=i32(point),y=i32(point+4);REQUIRE(!j||x>previous);previous=x;if(x>=a.lo&&x<=a.hi){if(!have){r=iv(y,y);have=true;}else{if(y<r.lo)r.lo=y;if(y>r.hi)r.hi=y;}}}int32_t endpoints[2];REQUIRE(lookup_endpoint(s,arg,(unsigned)value,a.lo,&endpoints[0])&&lookup_endpoint(s,arg,(unsigned)value,a.hi,&endpoints[1]));for(unsigned j=0;j<2;j++){if(!have){r=iv(endpoints[j],endpoints[j]);have=true;}else{if(endpoints[j]<r.lo)r.lo=endpoints[j];if(endpoints[j]>r.hi)r.hi=endpoints[j];}}r.boolean=r.lo==r.hi&&(r.lo==0||r.lo==Q);*work+=(uint32_t)value*2;}else if(op>=9&&op<=12){REQUIRE(op<11||(a.boolean&&b.boolean));r=(interval){0,Q,true};}else if(op==3){REQUIRE(scalar64((int64_t)a.lo+b.lo,&r.lo)&&scalar64((int64_t)a.hi+b.hi,&r.hi));r.boolean=r.lo==r.hi&&(r.lo==0||r.lo==Q);}else if(op==4){REQUIRE(scalar64((int64_t)a.lo-b.hi,&r.lo)&&scalar64((int64_t)a.hi-b.lo,&r.hi));r.boolean=r.lo==r.hi&&(r.lo==0||r.lo==Q);}else if(op==7){r=iv(a.lo<b.lo?a.lo:b.lo,a.hi<b.hi?a.hi:b.hi);r.boolean=r.boolean||(a.boolean&&b.boolean);}else if(op==8){r=iv(a.lo>b.lo?a.lo:b.lo,a.hi>b.hi?a.hi:b.hi);r.boolean=r.boolean||(a.boolean&&b.boolean);}else{REQUIRE(op!=6||b.lo>0||b.hi<0);int32_t aa[]={a.lo,a.hi},bb[]={b.lo,b.hi};bool initial=true;for(unsigned x=0;x<2;x++)for(unsigned y=0;y<2;y++){int32_t c;REQUIRE(scalar64(op==5?(int64_t)aa[x]*bb[y]/Q:(int64_t)aa[x]*Q/bb[y],&c));if(initial){r=iv(c,c);initial=false;}else{if(c<r.lo)r.lo=c;if(c>r.hi)r.hi=c;}}r.boolean=(op==5&&a.boolean&&b.boolean)||(r.lo==r.hi&&(r.lo==0||r.lo==Q));}depth-=inputs;stack[depth++]=r;REQUIRE(*work<=s->profile->limits->expression_instructions);}REQUIRE(depth==1);*result=stack[0];return true;}
static unsigned format_number(int32_t value,unsigned precision,char out[32]){if(precision>4)return 0;uint64_t magnitude=value<0?(uint64_t)(-(int64_t)value):(uint64_t)value,factor=1;for(unsigned i=0;i<precision;i++)factor*=10;uint64_t rounded=(magnitude*factor+Q/2)/Q,whole=rounded/factor;char reverse[12];unsigned at=0,n=0;if(value<0&&rounded)out[at++]='-';do{reverse[n++]=(char)('0'+whole%10);whole/=10;}while(whole);while(n)out[at++]=reverse[--n];if(precision){out[at++]='.';uint64_t fraction=rounded%factor;for(uint64_t divisor=factor/10;divisor;divisor/=10)out[at++]=(char)('0'+(fraction/divisor)%10);}out[at]=0;return at;}
static bool property_valid(osg_scene *s,unsigned node,unsigned property,int32_t lo,int32_t hi,bool boolean){uint8_t r[64];REQUIRE(node<s->nodes&&property>=1&&property<=6&&lo<=hi&&osg_scene_record(s,1,2,node,r,64));if(property==1)return boolean&&lo>=0&&hi<=Q;if(property==2||property==3){box b=rect(r+4),reach=rect(r+20);REQUIRE(lo%Q==0&&hi%Q==0);return property==2?b.x+lo/Q>=reach.x&&b.x+hi/Q+b.w<=reach.x+reach.w:b.y+lo/Q>=reach.y&&b.y+hi/Q+b.h<=reach.y+reach.h;}if(property==4)return lo>=0&&hi<=65535;if(property==5){REQUIRE(r[2]==2&&lo>=0&&(uint32_t)hi<count(s,2,1));for(int32_t i=lo;i<=hi;i++)REQUIRE(image_ref(s,r,(unsigned)i,1));}if(property==6){char out[32];REQUIRE(r[2]==5&&format_number(lo,u16(r+42),out)<=u16(r+50)&&format_number(hi,u16(r+42),out)<=u16(r+50));}return true;}
