static void line(osg_scene *s,box tile,box clip,int x0,int y0,int x1,int y1,unsigned width,uint16_t color){int dx=x1>x0?x1-x0:x0-x1,sx=x0<x1?1:-1,dy=y1>y0?y0-y1:y1-y0,sy=y0<y1?1:-1,error=dx+dy;for(;;){fill(s,tile,intersect(clip,(box){x0-(int)width/2,y0-(int)width/2,(int)width,(int)width}),color);if(x0==x1&&y0==y1)break;int twice=2*error;if(twice>=dy){error+=dy;x0+=sx;}if(twice<=dx){error+=dx;y0+=sy;}}}
static bool draw_node(osg_scene *s,box tile,unsigned index){uint8_t node[64];if(!osg_scene_record(s,1,2,index,node,64))return false;const osg_scene_properties *p=&s->properties[s->front][index];if(!p->visible)return true;box dest=rect(node+4);dest.x+=p->dx;dest.y+=p->dy;box clip=intersect(tile,intersect(dest,intersect(rect(node+12),content(s))));if(!clip.w||!clip.h)return true;if(node[2]==1)fill(s,tile,clip,p->color);else if(node[2]>=2&&node[2]<=4)return draw_image(s,tile,clip,node,p,dest);else if(node[2]==5)return draw_text(s,tile,clip,node,p,dest);else{uint8_t first[4],next[4];unsigned at=u16(node+38),n=u16(node+40);if(!osg_scene_record(s,1,9,at,first,4))return false;for(unsigned i=1;i<n;i++){if(!osg_scene_record(s,1,9,at+i,next,4))return false;line(s,tile,clip,s16(first)+p->dx,s16(first+2)+p->dy,s16(next)+p->dx,s16(next+2)+p->dy,u16(node+34),p->color);memcpy(first,next,4);}}return true;}
static bool compose(osg_scene *s,unsigned index){box t=grid_tile(s,index%s->tiles_x,index/s->tiles_x);uint8_t page[16],tile[12],member[2];if(!osg_scene_record(s,1,1,s->active_page,page,16))return false;for(int i=0;i<t.w*t.h;i++)s->tile[i]=u16(page+10);uint32_t key=(uint32_t)s->active_page*65536+(index/s->tiles_x)*256+index%s->tiles_x,lo=0,hi=count(s,1,11);while(lo<hi){uint32_t mid=lo+(hi-lo)/2;if(!osg_scene_record(s,1,11,mid,tile,12))return false;uint32_t current=(uint32_t)u16(tile)*65536+(uint32_t)u16(tile+4)*256+u16(tile+2);if(current<key)lo=mid+1;else hi=mid;}if(lo==count(s,1,11))return true;if(!osg_scene_record(s,1,11,lo,tile,12))return false;if((uint32_t)u16(tile)*65536+(uint32_t)u16(tile+4)*256+u16(tile+2)!=key)return true;for(unsigned i=0;i<u16(tile+8);i++)if(!osg_scene_record(s,1,12,u16(tile+6)+i,member,2)||!draw_node(s,t,u16(member)))return false;return true;}
unsigned osg_scene_render_slice(osg_scene *s,unsigned max_tiles,osg_write_pixels write,void *context){if(!s||!s->admitted||s->failed||!s->pending||!max_tiles)return 0;if(!write){s->failed=true;s->ready=false;s->pending=false;return 0;}unsigned written=0,total=s->tiles_x*s->tiles_y;while(s->cursor<total&&written<max_tiles){unsigned index=s->cursor++;if(!(s->dirty[index/8]&(1u<<(index%8))))continue;box t=grid_tile(s,index%s->tiles_x,index/s->tiles_x);if(!compose(s,index)||!write(context,t.x,t.y,t.w,t.h,s->tile)){s->failed=true;s->ready=false;s->pending=false;return written;}s->dirty[index/8]&=(uint8_t)~(1u<<(index%8));written++;}while(s->cursor<total&&!(s->dirty[s->cursor/8]&(1u<<(s->cursor%8))))s->cursor++;if(s->cursor==total){s->pending=false;s->awaiting_present=true;}return written;}
void osg_scene_presented(osg_scene *s,bool success){if(!s)return;if(!success){s->failed=true;s->ready=false;s->pending=false;s->awaiting_present=false;}else if(s->awaiting_present&&!s->failed){s->displayed=s->front;s->ready=true;s->awaiting_present=false;}}
int osg_scene_hit_test(osg_scene *s,int x,int y){if(!s||!s->admitted||s->failed||!s->ready||!s->connected)return -1;uint8_t hit[24],node[64];for(unsigned i=s->hits;i>0;i--){if(!osg_scene_record(s,1,8,i-1,hit,24))return -1;unsigned index=u16(hit+12);const osg_scene_properties *p=&s->properties[s->displayed][index];if(u16(hit+2)!=s->active_page||!p->visible||!inside(rect(hit+4),x,y))continue;if(!osg_scene_record(s,1,2,index,node,64))return -1;box b=rect(node+4);b.x+=p->dx;b.y+=p->dy;if(inside(intersect(b,intersect(rect(node+12),content(s))),x,y))return u16(hit);}return -1;}
bool osg_scene_get_usage(const osg_scene *s,osg_scene_usage *out){if(!s||!out||!s->admitted||s->failed)return false;*out=s->usage;return true;}
bool osg_scene_string(osg_scene *s,unsigned object,unsigned section,uint32_t offset,uint16_t bytes,char *out,size_t capacity){if(!s||!out||capacity<=(size_t)bytes||bytes>120)return false;out[0]=0;if(!string(s,object,section,offset,bytes,false))return false;const osg_render_section *t=table(s,object,section);if(!read_at(s,object,t->offset+offset,out,bytes))return false;out[bytes]=0;return true;}